import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Λογαριασμοί προσωπικού και διαχείριση","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/staff-administration.md","filePath":"el/plus/staff-administration.md"}'),l={name:"el/plus/staff-administration.md"};function s(o,a,n,d,c,p){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="λογαριασμοι-προσωπικου-και-διαχειριση" tabindex="-1">Λογαριασμοί προσωπικού και διαχείριση <a class="header-anchor" href="#λογαριασμοι-προσωπικου-και-διαχειριση" aria-label="Permalink to &quot;Λογαριασμοί προσωπικού και διαχείριση&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Έλεγχος πηγαίου κώδικα TransferBook+ v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, εταιρεία, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα για εκπαίδευση. Δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="πριν-απο-δημιουργια-λογαριασμου" tabindex="-1">Πριν από δημιουργία λογαριασμού <a class="header-anchor" href="#πριν-απο-δημιουργια-λογαριασμου" aria-label="Permalink to &quot;Πριν από δημιουργία λογαριασμού&quot;">​</a></h2><p>Η εγγραφή οδηγού στον κατάλογο και ο λογαριασμός σύνδεσης είναι διαφορετικά στοιχεία. Η δημιουργία οδηγού δεν συνεπάγεται έκδοση διαπιστευτηρίων. Η διαχείριση λογαριασμών γίνεται εξουσιοδοτημένα στο backend, όχι με δημόσια εγγραφή.</p><h2 id="εξουσιοδοτημενη-ενταξη" tabindex="-1">Εξουσιοδοτημένη ένταξη <a class="header-anchor" href="#εξουσιοδοτημενη-ενταξη" aria-label="Permalink to &quot;Εξουσιοδοτημένη ένταξη&quot;">​</a></h2><ol><li>Επιβεβαιώστε ταυτότητα, εργασιακή ή συμβατική σχέση, εταιρεία και καθήκοντα. Καταγράψτε την έγκριση του υπευθύνου.</li><li>Ζητήστε από τον διαχειριστή πλατφόρμας δημιουργία λογαριασμού και ενεργής εταιρικής συμμετοχής με τα ελάχιστα δικαιώματα. Το backend περιλαμβάνει το <code>scripts/provision-operator-user.mjs</code>: δέχεται email, όνομα, UUID εταιρείας και ρόλο, λαμβάνει αρχικό κωδικό από προστατευμένο περιβάλλον διεργασίας και αποθηκεύει hash scrypt. Δεν είναι οθόνη χειριστή.</li><li>Οι ρόλοι του συγκεκριμένου εργαλείου είναι company_admin, dispatcher, driver και viewer. Δεν εκχωρεί ρόλο διαχειριστή πλατφόρμας. Ελέγξτε ξεχωριστά τη σύνδεση του οδηγού με τον λογαριασμό· η συμμετοχή εταιρείας δεν την εξασφαλίζει.</li><li>Παραδώστε μοναδικά διαπιστευτήρια με ασφαλή τρόπο. Χρησιμοποιήστε ισχυρό κωδικό, χωρίς κοινόχρηστους λογαριασμούς ή δοκιμαστικούς κωδικούς. Το email επιβάτη είναι προαιρετικό, αλλά η ελεγμένη σύνδεση προσωπικού χρησιμοποιεί email και κωδικό.</li><li>Επιβεβαιώστε σύνδεση, σωστή εταιρεία, επιτρεπόμενες οθόνες και αποκλεισμένες ενέργειες με τον πραγματικό ρόλο. Για οδηγό ελέγξτε μόνο εξουσιοδοτημένες αναθέσεις. Η προσομοίωση από διαχειριστή δεν αποδεικνύει δικαιώματα οδηγού.</li></ol><h2 id="αλλαγες-και-αποχωρηση" tabindex="-1">Αλλαγές και αποχώρηση <a class="header-anchor" href="#αλλαγες-και-αποχωρηση" aria-label="Permalink to &quot;Αλλαγές και αποχώρηση&quot;">​</a></h2><p>Αν υπάρχει ήδη το κανονικοποιημένο email, το εργαλείο ενημερώνει διαπιστευτήρια και ενεργοποιεί λογαριασμό και συμμετοχή. Η επανάληψη αποτελεί ευαίσθητη αλλαγή λογαριασμού. Απαιτείται έγκριση και έλεγχος συμμετοχών πριν από επαναφορά. Σε αποχώρηση ζητήστε ανάκληση συμμετοχής, συνεδριών και κοινοποίησης θέσης από εξουσιοδοτημένο διαχειριστή και επαληθεύστε απόρριψη πρόσβασης. Μην διαγράφετε επιχειρησιακό ιστορικό για ανάκληση πρόσβασης.</p><p>Τυχόν μελλοντικές δημόσιες αιτήσεις οδηγών, προσωπικού και συνεργατών πρέπει να ελέγχονται πριν από δημιουργία λογαριασμού στο backend. Δεν επιβεβαιώνεται αυτόματη ενεργοποίηση ή γενική αυτοεξυπηρετούμενη διαχείριση προσωπικού.</p><p>Δείτε <a href="/el/developers/authentication.html">Ταυτοποίηση</a>, <a href="/el/developers/permissions.html">Ρόλοι</a> και <a href="/el/plus/drivers-and-rosters.html">Οδηγοί και βάρδιες</a>.</p>',10)])])}const f=e(l,[["render",s]]);export{m as __pageData,f as default};
